// `DefCollector` + `BuildReducedGraphVisitor` (def_collector.rs, build_reduced_graph.rs) on small `#![no_core]`
// crates, compared with the `resdump` probe (tools/probes/resdump) run with the `resdump-nocore` suite's
// arguments. Fixtures: graph_oracle/cases/<name>.rs -> <name>.resdump.txt / <name>.stderr, regenerated by
// `bun src/rustc_resolve/graph_oracle/gen.ts` (rustc 1.101.0-nightly (6f5da406b 2026-10-10)); with
// RUST_TS_REQUIRE_PROBES=1 and the probe built, a test re-runs the probe and checks that they are current.
//
// The run follows resolver_new.test.ts (`with_tcx`: the `GlobalCtxt` built the way
// `create_and_enter_global_ctxt` builds it, crate name = file stem), then `Resolver::new` and the
// expansion step of `configure_and_expand` (`MacroExpander::expand_crate`, which assigns the `NodeId`s
// and calls `visit_ast_fragment_with_placeholders` -> `collect_definitions`). The cases have no macros,
// no imports and `no_core` (nothing is injected), so the other steps of `configure_and_expand` add
// nothing. Compared sections (the parts of the probe's dump that the def collector and the reduced
// graph determine):
// - `definitions` (DefKind, DefKey, DefPathHash, in DefIndex order) and `visibilities_for_hashing`: as printed.
// - `owners`: the owner ids and their `node_id_to_def_id` maps (`lifetime_elision_allowed` and the other
//   per-owner maps are set by late resolution).
// - `module_children`: computed here from the modules' resolution tables the way imports.rs's
//   `finalize_resolutions_in` does for modules without imports (non-glob declarations only).
//
// Stand-ins for pending lanes (test-only, installed only while the real method is still the stub
// placeholder): `resolve_dollar_crates`, `visit_ast_fragment_with_placeholders`, `check_reserved_macro_name`
// (res-macros), `resolve_imports`, `try_plant_decl_into_local_module` (res-imports). Each is the upstream
// body restricted to what these cases reach; anything beyond calls `unported("test stand-in: ..")`.
//
// PENDING: cases that need other lanes' code (name -> the `unported` they reach). Root deletes an entry
// once it matches; until then the test checks that the case stops at exactly that point.
import { afterAll, beforeAll, describe, expect, test } from "bun:test";
import { existsSync, readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import "./lib.ts";
import { type Attribute, type Crate } from "../rustc_ast/lib.ts";
import { debug_NodeId } from "../rustc_ast/node_id.ts";
import { Untracked } from "../rustc_crate_store/cstore.ts";
import type { CrateStore } from "../rustc_crate_store/cstore.ts";
import { Steal } from "../rustc_data_structures/steal.ts";
import { compiler_entrypoint } from "../rustc_driver_impl/lib.ts";
import { ExtCtxt } from "../rustc_expand/base.ts";
import * as rustc_expand_config from "../rustc_expand/config.ts";
import { pre_configure_attrs } from "../rustc_expand/config.ts";
import { type AstFragment, ExpansionConfig } from "../rustc_expand/expand.ts";
import { debug_DefKind, debug_Res } from "../rustc_hir/def.ts";
import { debug_DefKey, Definitions } from "../rustc_hir_id/definitions.ts";
import { type Config, run_compiler } from "../rustc_interface/interface.ts";
import * as limits from "../rustc_interface/limits.ts";
import { AttributeParser } from "../rustc_attr_parsing/lib.ts";
import type { Session } from "../rustc_session/session.ts";
import type { Limit } from "../rustc_structures/limit.ts";
import { DEFAULT_QUERY_PROVIDERS, parse } from "../rustc_interface/passes.ts";
import { DepGraph } from "../rustc_middle/dep_graph/graph.ts";
import { clone_Providers as clone_HookProviders } from "../rustc_middle/hooks.ts";
import { debug_ModChild, type ModChild } from "../rustc_middle/middle/resolve.ts";
import { clone_ExternProviders, clone_Providers } from "../rustc_middle/query/query_api.ts";
import { CurrentGcx, TyCtxt, TyCtxtFeed } from "../rustc_middle/ty/context.ts";
import { debug_Visibility, type Visibility } from "../rustc_middle/ty/mod.ts";
import { query_system } from "../rustc_query_impl/lib.ts";
import { CrateNum, DEF_ID_DEBUG, type DefId, DefIndex, debug_DefPathHash, debug_LocalModId, LOCAL_CRATE, LocalDefId, type ModId, ModId_eq, StableCrateId } from "../rustc_span/def_id.ts";
import { type LocalExpnId, update_dollar_crate_names } from "../rustc_span/hygiene.ts";
