import type { IdentKey } from "./lib.gen.ts";
import type { Namespace } from "../rustc_hir/def.ts";

const HERE = import.meta.dir;
const CASES = join(HERE, "graph_oracle", "cases");

const PENDING: Record<string, string> = {
  p_duplicate: "rustc_resolve::diagnostics::impls::Resolver::report_conflict",
  // The test's own module_children dump does not yet follow import declarations (use finalize_resolutions_in).
  p_extern_crate_self: "test: module_children of imports (res-imports)",
  // With real import resolution, `use` paths reach late resolution (lane res-late).
  use_trees: "rustc_resolve::late::PathSource::is_expected",
  p_macro_escape: "rustc_resolve::diagnostics::impls::Resolver::dcx",
  p_macro_rules: "rustc_index::bit_set::DenseBitSet::new_filled",
  p_vis_restricted: "rustc_resolve::late::PathSource::is_expected",
};

// PARTIAL: cases whose imports the `resolve_imports` stand-in leaves unresolved (import resolution creates no
// definitions and feeds no visibilities, so those sections and the owners are still compared); their
// `module_children` need res-imports. Root deletes an entry once res-imports has landed.
const PARTIAL: Record<string, string> = {};
let imports_deferred = false;

// ---- the stand-ins for pending lanes ------------------------------------------------------------------

type Shim = { name: string; path: string; target?: object; fn: (this: Resolver, ...args: never[]) => unknown };
const SHIMS: Shim[] = [
  {
    // imports.rs:286 `NameResolution::new` (reached through lib.rs's `resolution_or_default`)
    name: "new",
    path: "rustc_resolve::imports::NameResolution::new",
    target: imports.NameResolution,
    fn: function (orig_ident_span: Span): imports.NameResolution {
      return new imports.NameResolution(new Set(), undefined, undefined, orig_ident_span);
    } as unknown as (this: Resolver, ...args: never[]) => unknown,
  },
  {
    // macros.rs:189 `<Resolver as ResolverExpand>::resolve_dollar_crates`
    name: "resolve_dollar_crates",
    path: "rustc_resolve::macros::Resolver",
    fn: function (this: Resolver): void {
      update_dollar_crate_names((ctxt) => {
        const ident = Ident.new(kw.DollarCrate, Span.with_ctxt(DUMMY_SP, ctxt));
        return this.resolve_crate_root(ident).name() ?? kw.Crate;
      });
    },
  },
  {
    // macros.rs:196 `<Resolver as ResolverExpand>::visit_ast_fragment_with_placeholders`
    name: "visit_ast_fragment_with_placeholders",
    path: "rustc_resolve::macros::Resolver",
    fn: function (this: Resolver, expansion: LocalExpnId, fragment: AstFragment): void {
      // Integrate the new AST fragment into all the definition and module structures.
      // We are inside the `expansion` now, but other parent scope components are still the same.
      const base = unwrap(this.invocation_parent_scopes.get(expansion));
      const parent_scope = new ParentScope(base.module, expansion, base.macro_rules, base.derives);
      const output_macro_rules_scope = collect_definitions(this, fragment, parent_scope);
      this.output_macro_rules_scopes.set(expansion, output_macro_rules_scope);

      const module = parent_scope.module.expect_local();
      module.unexpanded_invocations.borrow_mut(this).value.delete(expansion);
      // `self.invocation_parent(expansion)` (macros.rs:177)
      const unexpanded_invocations = this.impl_unexpanded_invocations.get(unwrap(this.invocation_parents.get(expansion)).parent_def);
      if (unexpanded_invocations !== undefined) {
        unexpanded_invocations.delete(expansion);
      }
    } as (this: Resolver, ...args: never[]) => unknown,
  },
  {
    // macros.rs:1195 `check_reserved_macro_name`
    name: "check_reserved_macro_name",
    path: "rustc_resolve::macros::Resolver",
    fn: function (this: Resolver, name: Symbol, _span: Span, _res: Res): void {
      // Reserve some names that are not quite covered by the general check
      // performed on `Resolver::builtin_attrs`.
      if (name === sym.cfg || name === sym.cfg_attr) {
        unported("test stand-in: check_reserved_macro_name for cfg/cfg_attr (res-macros)");
      }
    } as (this: Resolver, ...args: never[]) => unknown,
  },
  {
    // imports.rs:775 `resolve_imports`
    name: "resolve_imports",
    path: "rustc_resolve::imports::Resolver",
    fn: function (this: Resolver): void {
      // With no indeterminate imports the loop runs once over an empty list and changes nothing. With imports
      // (PARTIAL cases) they stay unresolved and `module_children` is not compared.
      if (this.indeterminate_imports.length !== 0) imports_deferred = true;
    },
  },
  {
    // imports.rs:624 `try_plant_decl_into_local_module` (+ imports.rs:673 `update_local_resolution`)
    name: "try_plant_decl_into_local_module",
    path: "rustc_resolve::imports::Resolver",
    fn: function (this: Resolver, ident: IdentKey, orig_ident_span: Span, ns: Namespace, decl: Decl): Result<undefined, Decl> {
      assert(decl.ambiguity.get() === undefined);
      assert(decl.ambiguity_vis_max.get() === undefined);
      assert(decl.ambiguity_vis_min.get() === undefined);
      const module = unwrap(decl.parent_module).expect_local();
      assert(this.is_accessible_from(decl.vis(), module.to_module()));
      const res = decl.res();
      this.check_reserved_macro_name(ident.name, orig_ident_span, res);
      const key = BindingKey.new_disambiguated(ident, ns, () => {
        module.underscore_disambiguator.update(this, (d) => d + 1);
        return module.underscore_disambiguator.get();
      });
      // `update_local_resolution`: `f` on the resolution, then the module's glob importers.
      const resolution = this.resolution_or_default(module.to_module(), key, orig_ident_span).borrow_mut(this).value;
      if (res.$ === "Err") unported("test stand-in: planting Res::Err (res-imports)");
      if (decl.is_glob_import()) unported("test stand-in: planting a glob declaration (res-imports)");
      if (resolution.glob_decl !== undefined || resolution.single_imports.size !== 0) unported("test stand-in: determined_decl with imports (res-imports)");
      if (resolution.non_glob_decl !== undefined) return Err(resolution.non_glob_decl);
      resolution.non_glob_decl = decl;
      if (module.glob_importers.value.length !== 0) unported("test stand-in: glob importers (res-imports)");
      return Ok(undefined);
    } as (this: Resolver, ...args: never[]) => unknown,
  },
];

/**
 * Whether `target[name]` is still a stub: an `unported_methods` placeholder (src/rust_ts/stubs.ts) or a stub
 * body that only calls `unported("<path>")`.
 */
function is_placeholder(target: object, name: string, path: string): boolean {
  const fn = (target as Record<string, unknown>)[name];
  if (typeof fn !== "function") return false;
  const src = fn.toString();
  return /return unported\(`\$\{path\}::\$\{name\}`\)/.test(src) || src.includes(`unported("${path}")`);
}

const saved: [Record<string, unknown>, string, unknown][] = [];
beforeAll(() => {
  for (const shim of SHIMS) {
    const target = (shim.target ?? Resolver.prototype) as Record<string, unknown>;
    if (!is_placeholder(target, shim.name, shim.path)) continue;
    saved.push([target, shim.name, target[shim.name]]);
    target[shim.name] = shim.fn;
  }
});
afterAll(() => {
  for (const [target, name, fn] of saved) target[name] = fn;
});

// Stand-in for rustc_middle's `query_feed` re-feed check (calls.rs:215; calls.ts leaves it `unported` until query
// values are stably hashed): `build_reduced_graph_for_item` and `build_reduced_graph_for_struct_variant` both
// feed a struct's / union's `visibility`. Upstream compares the stable hashes of the old and the new value and
// does nothing when they are equal; here equal values (same variant, same `ModId`) do nothing, anything else
// stops the case. Installed per case (`run_case`), keyed on the `LocalDefId`.
function with_visibility_refeed<R>(f: () => R): R {
  const proto = TyCtxtFeed.prototype as unknown as Record<string, (this: TyCtxtFeed<LocalDefId>, v: Visibility<ModId>) => void>;
  const orig = proto.visibility!;
  const fed = new Map<LocalDefId, Visibility<ModId>>();
  proto.visibility = function (this: TyCtxtFeed<LocalDefId>, v: Visibility<ModId>): void {
    const key = this.key();
    const old = fed.get(key);
    if (old !== undefined) {
      const same = old.$ === v.$ && (old.$ === "Public" || ModId_eq(old._0, (v as { _0: ModId })._0));
      if (!same) unported("test stand-in: re-feeding a different visibility (query_feed stable hashing)");
      return;
    }
    fed.set(key, v);
    orig.call(this, v);
  };
  try {
    return f();
  } finally {
    proto.visibility = orig;
  }
}

// ---- the compilation ------------------------------------------------------------------------------------

class CaptureConfig extends Error {}

/** The `interface::Config` rustc's driver builds from `args` (as resolver_new.test.ts). */
function config_from_args(args: string[]): Config {
  let config: Config | undefined;
  try {
    compiler_entrypoint(["rustc", ...args], {
      config(c: Config) {
        config = c;
        throw new CaptureConfig();
      },
    });
  } catch (e) {
    if (!(e instanceof CaptureConfig)) throw e;
  }
  if (config === undefined) throw new Error("no config");
  return config;
}

const NO_CSTORE = new Proxy({}, { get: () => () => unported("rustc_metadata::creader::CStore (wave 11)") }) as unknown as CrateStore;

/** As resolver_new.test.ts's `with_tcx`, for `file` (crate name = the file stem). */
function with_tcx<R>(file: string, f: (tcx: TyCtxt) => R): R {
  const config = config_from_args(["--target", "x86_64-unknown-linux-gnu", "--edition=2015", "-Zcrate-attr=feature(no_core)", "-Zcrate-attr=no_core", file]);
  let out: R | undefined;
  run_compiler(config, (compiler) => {
    const sess = compiler.sess;
    const krate = parse(sess);
    const pre_configured_attrs = pre_configure_attrs(sess, krate.attrs);
    // PORT (test): `get_crate_name` -> the file stem; `collect_crate_types` -> `bin`.
    const crate_name = Symbol.intern(file.replace(/^.*\//, "").replace(/\.rs$/, ""));
    const stable_crate_id = StableCrateId.new(crate_name, true, [...sess.opts.cg.metadata], sess.cfg_version);
    const untracked = new Untracked(NO_CSTORE, [], Definitions.new(stable_crate_id), new Map(), undefined);
    const base = DEFAULT_QUERY_PROVIDERS();
    const queries = clone_Providers(base.queries);
    const extern = clone_ExternProviders(base.extern_queries);
    const hooks = clone_HookProviders(base.hooks);
    provide(queries);
    out = TyCtxt.create_global_ctxt(
      { value: undefined },
      sess,
      ["Executable"],
      stable_crate_id,
      untracked,
      undefined,
      DepGraph.new_disabled(),
      query_system(queries, extern, undefined, false, false),
      hooks,
      CurrentGcx.new(),
      (tcx) => {
        const r = tcx.create_crate_num(stable_crate_id);
        if (r.$ !== "Ok") return panic("create_crate_num");
        r._0.crate_name(crate_name);
        const unit = tcx.feed_unit_query();
        unit.features_query(rustc_expand_config.features(tcx.sess, pre_configured_attrs, crate_name));
        unit.crate_for_resolver(Steal.new<[Crate, Attribute[]]>([krate, pre_configured_attrs], "(rustc_ast::ast::Crate, thin_vec::ThinVec<rustc_ast::ast::Attribute>)"));
        return f(tcx);
      },
    );
  });
  return out as R;
}

/** `rustc_middle::ty::context::tls`-aware `{:?}` of a `DefId` (callbacks.rs `def_id_debug` + `def_path_debug_str`), local crate only. */
function def_id_debug(tcx: TyCtxt): (def_id: DefId, f: Fmt) => string {
  return (def_id) => {
    if (def_id.krate !== LOCAL_CRATE) throw new Error("test helper: local DefIds only");
    const scid = tcx.stable_crate_id(LOCAL_CRATE);
    const hi16 = (StableCrateId.as_u64(scid) >> 48n).toString(16).padStart(4, "0");
    const local = unwrap(def_id.as_local());
    const path = tcx.definitions_untracked().def_path(local).to_string_no_crate_verbose();
    return `DefId(${CrateNum.as_u32(def_id.krate)}:${DefIndex.as_u32(def_id.index)} ~ ${Symbol.as_str(tcx.crate_name(LOCAL_CRATE))}[${hi16}]${path})`;
  };
}

/** passes.rs:1523 `get_recursion_limit` (not exported by passes.ts; `tcx.recursion_limit()` needs HIR). */
function get_recursion_limit(krate_attrs: readonly Attribute[], sess: Session): Limit {
  const attr = AttributeParser.parse_limited_sym_should_emit(sess, krate_attrs, [sym.recursion_limit], DUMMY_SP, undefined, {
    $: "EarlyFatal",
    also_emit_lints: false,
  });
  return limits.get_recursion_limit(attr === undefined ? [] : [attr], sess);
}

/** `Resolver::new`, then `configure_and_expand`'s expansion step; returns the compared sections. */
function run_case(file: string, skip?: string): Map<string, string[]> {
  return with_visibility_refeed(() => with_tcx(file, (tcx) => {
    const sess = tcx.sess;
    const arenas = Resolver.arenas();
    void tcx.registered_attr_tools(null);
    void tcx.registered_lint_tools(null);
    const [krate0, pre_configured_attrs] = tcx.crate_for_resolver(null).steal() as [Crate, Attribute[]];
    const resolver = Resolver.new(tcx, pre_configured_attrs, krate0.spans.inner_span, krate0.spans.inject_use_span, arenas);

    // `configure_and_expand` (passes.rs:136): no lint store (no lints are emitted without macros), no builtin
    // macros needed, `no_core` (no standard library imports).
    const cfg = new ExpansionConfig(
      tcx.crate_name(LOCAL_CRATE),
      tcx.features(),
      get_recursion_limit(pre_configured_attrs, sess),
      sess.opts.unstable_opts.trace_macros,
      sess.is_test_crate(),
      sess.opts.unstable_opts.span_debug,
      sess.opts.unstable_opts.proc_macro_backtrace,
    );
    const ecx = ExtCtxt.new(sess, cfg, resolver, undefined);
    ecx.monotonic_expander().expand_crate(krate0);
    expect(sess.dcx().has_errors()).toBeUndefined();

    const old_debug = DEF_ID_DEBUG.swap(def_id_debug(tcx));
    try {
      return dump(tcx, resolver, skip);
    } finally {
      DEF_ID_DEBUG.swap(old_debug);
    }
  }));
}

/** The compared sections, printed like tools/probes/resdump/main.rs. */
function dump(tcx: TyCtxt, resolver: Resolver, skip: string | undefined): Map<string, string[]> {
  const sec = new Map<string, string[]>();
  const di = (id: LocalDefId) => def_id_debug(tcx)(LocalDefId.to_def_id(id), PLAIN);

  sec.set(
    "visibilities_for_hashing",
    resolver.visibilities_for_hashing.map(([id, vis]) => `${di(id)} ${debug_Visibility(vis, PLAIN, debug_LocalModId)}`),
  );

  // `finalize_resolutions_in` (imports.rs:1880) for modules without imports.
  const module_children: string[] = [];
  const modules = resolver.local_modules
    .filter((m) => m.opt_def_id() !== undefined)
    .sort((a, b) => DefIndex.as_u32(a.def_id().index) - DefIndex.as_u32(b.def_id().index));
  for (const module of skip === "module_children" ? [] : modules) {
    const children: ModChild[] = [];
    for (const [key, name_resolution_ref] of resolver.resolutions(module)) {
      const nr = name_resolution_ref.value;
      if (nr.glob_decl !== undefined || nr.single_imports.size !== 0) unported("test: module_children of a module with imports (res-imports)");
      const decl = nr.non_glob_decl;
      if (decl === undefined) continue;
      if (decl.kind.$ !== "Def" || decl.descent_to_ambiguity() !== undefined) unported("test: module_children of imports (res-imports)");
      const res = decl.res();
      if (res.$ === "Err") continue;
      children.push({ ident: key.ident.orig(nr.orig_ident_span), res: res as Res as never, vis: decl.vis(), reexport_chain: decl.reexport_chain() });
    }
    if (children.length === 0) continue;
    module_children.push(def_id_debug(tcx)(module.def_id(), PLAIN));
    for (const child of children) module_children.push(`  ${debug_ModChild(child, PLAIN)}`);
  }
  sec.set("module_children", module_children);

  const owners: string[] = [];
  for (const [id, data] of [...resolver.owners].sort((x, y) => x[0] - y[0])) {
    owners.push(`${debug_NodeId(id, PLAIN)} def_id=${di(data.def_id)}`);
    for (const [nid, def_id] of [...data.node_id_to_def_id].sort((x, y) => x[0] - y[0])) {
      owners.push(`  node_id_to_def_id ${debug_NodeId(nid, PLAIN)} ${di(def_id)}`);
    }
  }
  sec.set("owners", owners);

  const defs = tcx.definitions_untracked();
  const definitions: string[] = [];
  for (let i = 0; i < defs.num_definitions(); i++) {
    const id = LocalDefId.of(i as Parameters<typeof LocalDefId.of>[0]);
    definitions.push(`${di(id)} ${debug_DefKind(tcx.def_kind(id), PLAIN)} ${debug_DefKey(defs.def_key(id), PLAIN)} ${debug_DefPathHash(defs.def_path_hash(id), PLAIN)}`);
  }
  sec.set("definitions", definitions);
  void debug_Res;
  return sec;
}

/** The probe's output as `section -> lines`, restricted to what `dump` prints. */
function parse_resdump(text: string): Map<string, string[]> {
  const sec = new Map<string, string[]>();
  let cur: string[] | undefined;
  for (const line of text.split("\n")) {
    const m = /^== (\w+)(?: \((\d+)\))?$/.exec(line);
    if (m) {
      cur = [];
      sec.set(m[1]!, cur);
    } else if (line !== "" && cur) cur.push(line);
  }
  const owners = (sec.get("owners") ?? [])
    .filter((l) => !l.startsWith("  ") || l.startsWith("  node_id_to_def_id "))
    .map((l) => l.replace(/ lifetime_elision_allowed=(true|false)$/, ""));
  const out = new Map<string, string[]>();
  for (const name of ["visibilities_for_hashing", "module_children", "owners", "definitions"]) {
    out.set(name, name === "owners" ? owners : unwrap(sec.get(name), `section ${name}`));
  }
  return out;
}

const NAMES = readdirSync(CASES)
  .filter((f) => f.endsWith(".rs"))
  .map((f) => f.slice(0, -3))
  .sort();

describe("def collector + reduced graph vs the resdump probe", () => {
  for (const name of NAMES) {
    test(name, () => {
      const oracle = parse_resdump(readFileSync(join(CASES, `${name}.resdump.txt`), "utf8"));
      const pending = PENDING[name];
      if (pending !== undefined) {
        let err: unknown;
        try {
          run_case(join(CASES, `${name}.rs`));
        } catch (e) {
          err = e;
        }
        expect(err).toBeInstanceOf(Unported);
        expect((err as Unported).what).toContain(pending);
        return;
      }
      imports_deferred = false;
      const skip = PARTIAL[name];
      const got = run_case(join(CASES, `${name}.rs`), skip);
      expect(imports_deferred).toBe(skip !== undefined);
      if (skip !== undefined) oracle.delete(skip);
      expect(oracle.size).toBe(skip === undefined ? 4 : 3);
      for (const [section, lines] of oracle) {
        expect({ section, lines: got.get(section) }).toEqual({ section, lines });
      }
    });
  }
});

test("the fixtures are the current probe output", () => {
  const req = process.env.RUST_TS_REQUIRE_PROBES === "1";
  const data = process.env.RUST_TS_DATA;
  const probe = data === undefined ? undefined : join(data, "target", "probes", "release", "resdump");
  if (probe === undefined || !existsSync(probe)) {
    if (req) throw new Error(`ERROR: resdump probe missing (${probe}); bun scripts/probes.ts build resdump`);
    return;
  }
  const { ARGS } = require("./graph_oracle/args.ts") as typeof import("./graph_oracle/args.ts");
  for (const name of NAMES) {
    const r = Bun.spawnSync([probe, ...ARGS(true), `${name}.rs`], { cwd: CASES, env: { ...process.env, RUSTC_ICE: "0", RUST_BACKTRACE: "0" } });
    expect({ name, out: new TextDecoder().decode(r.stdout) }).toEqual({ name, out: readFileSync(join(CASES, `${name}.resdump.txt`), "utf8") });
    expect({ name, err: `exit ${r.exitCode}\n${new TextDecoder().decode(r.stderr)}` }).toEqual({ name, err: readFileSync(join(CASES, `${name}.stderr`), "utf8") });
  }
});
